"""Manually cleaned couplets from 'Κείμενα Κυπριακής Λογοτεχνίας' τ. Α΄ (ΥΠΠ Κύπρου), pp. 28-29 «Ερωτικά δίστιχα».
Text taken from pdftotext output with the synizesis marks (υ) removed (τζιυ -> τζι)."""
import json
OUT = "/home/stelios/repos/mougia/data/raw/book_schcy_keimena/extracted.jsonl"
URL = "https://www.openbook.gr/keimena-kypriakis-logotechnias/"
C = [
 (28, "Χατζηιωάννου 1961", "Τα σείλη σου τα κότσινα θέλω να τα φιλήσω,\nτζαι τζείνα στάσσουν το κρασίν, φοούμαι μεν μεθύσω."),
 (28, "Χατζηιωάννου 1961", "Κόρη, να πεις της μάνας σου να κάμει τζι άλλην κόρην,\nσαν έκαψεν την Βενεδκιάν, να κάψει τζαι την Πόλην."),
 (28, "Χατζηιωάννου 1961", "Κόρη, π’ αφ’ ης σ’ αγάπησα ο νους μου σκανταλίστην,\nόσος επήεν πάνω σου τζι ο άλλος εσκορπίστην."),
 (28, "Χατζηιωάννου 1961", "Αναστενάζω, τρέμ’ η γή, χαμαί τσακρούν οι πέτρες,\nτζαι τρέχουσιν τ’ αμμάδκια μου σαν τρέχουν οι χολέτρες."),
 (28, "Χατζηιωάννου 1961", "Στους κάμπους αναστέναξα τζαι τα βουνά ραήκαν,\nπου πήραν την αγάπην μου τζαι δεν μου την αφήκαν."),
 (28, "Χατζηιωάννου 1961", "Τα τζύμματα της θάλασσας τζαι τα λαμπρά μ’ εμέναν\nποττέ τους εν-ι-σβήννουσιν, γιατ’ έν συμπελλισμένα."),
 (29, "Χατζηιωάννου 1961", "Ροδοντυμένη αγάπη μου, τ’ αδόνι’ άμαυσε δούσιν,\nθαρρούν πως έν η άννοιξη τζαι γλυκοτζελαδούσιν."),
 (29, "Χατζηιωάννου 1961", "Νυχτώννει τζαι παρακαλώ πότε να ξημερώσει,\nγια να σε δουν τ’ αμμάδκια μου τζι ο νους μου να μερώσει."),
 (29, "Χατζηιωάννου 1961", "Βασιλιτζιάν τζαι λασμαρίν τζι αθθόν του γλυκανίσσου\nο έρωτας τα μάζεψεν τζι έκαμεν το κορμίν σου."),
 (29, "Χατζηιωάννου 1961", "Ο έρωτας δενν έν αθθός μαζίν του για να παίξεις\nμον’ ένι βάτος μ’ αγκαθκιές τζι αλοίμονον αν μπλέξεις."),
 (29, "Χατζηιωάννου 1961", "Σαν μέραν του καλοτζαιρκού, που ’ν του νερού καμένη,\nέτσ’ ένι τζι η καρτούλλα μου για σέν’ πεθυμισμένη."),
 (29, "Χατζηιωάννου 1961", "Αντάν να βκεί στον ηλιακόν να δκιανευτεί τζαι δώ την,\nπαθθάννω σαν την θάλασσαν όταν την λάμνουν νότοι."),
 (29, "Χατζηιωάννου 1961", "Άνταν δικλήσουν τζαι με δούν τα μαύρα της τ’ αμμάθτζια\nσαν να με πιλατεύκουσιν του κάστρου τα κομμάθτζια."),
 (29, "Χατζηιωάννου 1961", "Σάν το λεμόνιν τζίτρινον μ’ έκαμεν ο σεβτάς σου,\nπου δεν με ’φήννεις να χαρώ πέντε λεπτά μιτά σου."),
 (29, "Μόντης-Χριστοφίδης 1965", "Είπουν της «Δος μου ’να φιλίν» τζ’ είπεν μου «Πκιάε δέκα»\nτζ’ είπουν τζ’ εγιώ ’πού μέσα μου «Ίντα καλή γεναίκα»!"),
 (29, "Μόντης-Χριστοφίδης 1965", "Πεζούνιν, αρκοπέζουνον ήσουν τζ’ εμέρωσά σε\nτζαι τώρα που σ’ εμέρωσα έφυες τζ’ έχασά σε."),
]
with open(OUT, "w", encoding="utf-8") as f:
    for p, src, t in C:
        f.write(json.dumps({"text": t, "source": "Κείμενα Κυπριακής Λογοτεχνίας, τ. Α΄ (ΥΠΠ/ΠΙ Κύπρου, 2015/2017)", "url": URL,
            "page": p, "section": "Ερωτικά δίστιχα", "ocr_confidence": "high",
            "notes": f"born-digital PDF; textbook cites: {'Κ.Π. Χατζηιωάννου, Κυπριακά διαλεκτικά κείμενα, 1961' if src.startswith('Χατ') else 'Κ. Μόντης - Α. Χριστοφίδης, Κυπριακή Ανθολογία, 1965'}; synizesis marks removed"}, ensure_ascii=False) + "\n")
print(len(C))
